     1|/**
     2| * IVX IA Brain Memory — natural-language command parsing + greeting builder.
     3| *
     4| * Parses the owner/user memory commands:
     5| *   - "remember my name is ___"            → set the caller's own name
     6| *   - "remember this user is ___"          → set a name (owner managing a user)
     7| *   - "change my name to ___"              → rename the caller
     8| *   - "forget this name" / "forget my name"→ clear the remembered name
     9| *   - "show what you remember"             → recall the stored profile
    10| *
    11| * And builds the cross-conversation greeting:
    12| *   "Good morning Ivan Perez. IVX IA is ready."
    13| */
    14|import {
    15|  IVX_IA_NAME,
    16|  deleteProfile,
    17|  forgetName,
    18|  getProfile,
    19|  isSensitiveValue,
    20|  listProfiles,
    21|  upsertProfile,
    22|  type UserProfile,
    23|} from './ivx-ia-memory-store';
    24|
    25|export type MemoryCommandKind =
    26|  | 'remember_name'
    27|  | 'change_name'
    28|  | 'forget_name'
    29|  | 'show_memory';
    30|
    31|export type MemoryCommand = {
    32|  kind: MemoryCommandKind;
    33|  /** The extracted name value, when the command carries one. */
    34|  value: string;
    35|};
    36|
    37|// Memory read patterns: the owner asks IVX IA to recall what it remembers.
    38|const SHOW_MEMORY_PATTERNS: readonly RegExp[] = [
    39|  /\bwhat\s+is\s+my\s+name\b/i,
    40|  /\bwho\s+am\s+i\b/i,
    41|  /\bdo\s+you\s+(?:know|remember)\s+me\b/i,
    42|  /\bshow\s+(?:me\s+)?what\s+you\s+remember\b/i,
    43|  /\bwhat\s+do\s+you\s+remember\b/i,
    44|  /\bshow\s+(?:my\s+)?(?:memory|profile)\b/i,
    45|  /\bwhat\s+do\s+you\s+know\s+about\s+me\b/i,
    46|];
    47|
    48|// Memory write patterns: the owner tells IVX IA to remember identity data.
    49|// These patterns are intentionally broad so common phrasing like "my name is X"
    50|// or "save this now" are captured and not misclassified as clarification.
    51|const REMEMBER_NAME_PATTERNS: readonly RegExp[] = [
    52|  /\b(?:remember|save)\s+(?:that\s+)?my\s+name\s+is\s+(.+?)(?:\s+(?:and\s+)?(?:save|remember|store)\s+it)?$/i,
    53|  /\bmy\s+name\s+is\s+(.+?)(?:\s+(?:and\s+)?(?:save|remember|store)\s+it)?$/i,
    54|  /\b(?:save|remember|store)\s+my\s+name\s+as\s+(.+)$/i,
    55|  /\b(?:remember|save)\s+(?:that\s+)?this\s+user\s+(?:is|name\s+is|is\s+called)\s+(.+)$/i,
    56|  /\b(?:remember|save)\s+(?:that\s+)?i\s*['’]?m\s+(.+?)(?:\s+(?:and\s+)?(?:save|remember|store)\s+it)?$/i,
    57|  /\b(?:remember|save)\s+(?:that\s+)?i\s+(?:work\s+at|am\s+(?:the\s+)?(?:owner|ceo|founder)\s+of)\s+(.+)$/i,
    58|  /\b(?:remember|save)\s+(?:that\s+)?my\s+(?:company|role|email|language)\s+is\s+(.+)$/i,
    59|  /\bmy\s+(?:company|role|email|language)\s+is\s+(.+?)(?:\s*,?\s*(?:please\s+)?(?:save|remember|store)\s+(?:this|it|that))?\.?$/i,
    60|  /\bmy\s+preferred\s+(?:language|name|company|role|email)\s+is\s+(.+?)(?:\s*,?\s*(?:please\s+)?(?:save|remember|store)\s+(?:this|it|that))?\.?$/i,
    61|  /\bi\s+prefer\s+to\s+be\s+called\s+(.+?)(?:\s*,?\s*(?:please\s+)?(?:save|remember|store)\s+(?:this|it|that))?\.?$/i,
    62|  /\bi\s+(?:work\s+at|am\s+(?:the\s+)?(?:owner|ceo|founder)\s+of)\s+(.+?)(?:\s*,?\s*(?:please\s+)?(?:save|remember|store)\s+(?:this|it|that))?\.?$/i,
    63|  /\bmy\s+(?:company|role|email|language)\s+is\s+.{2,60}?\b(?:and\s+)?(?:i\s+prefer\s+to\s+be\s+called|call\s+me|my\s+name\s+is)\s+(.+?)(?:\s*,?\s*(?:please\s+)?(?:save|remember|store)\s+(?:this|it|that))?\.?$/i,
    64|];
    65|
    66|const CHANGE_NAME_PATTERNS: readonly RegExp[] = [
    67|  /\b(?:change|update)\s+my\s+name\s+to\s+(.+)$/i,
    68|  /\bcall\s+me\s+(.+)$/i,
    69|];
    70|
    71|const FORGET_NAME_PATTERNS: readonly RegExp[] = [
    72|  /\bforget\s+(?:this|my)\s+name\b/i,
    73|  /\bforget\s+who\s+i\s+am\b/i,
    74|];
    75|
    76|/** Return true if the prompt is clearly a save/remember request about identity. */
    77|function isMemorySaveRequest(text: string): boolean {
    78|  const lower = text.toLowerCase();
    79|  return /\b(?:remember|remembering|save|saving|store|storing)\s+/.test(lower)
    80|    && /\b(?:my\s+name|i\s*['’]?m|i\s+am|who\s+i\s+am|my\s+(?:company|role|email|language))\b/.test(lower);
    81|}
    82|
    83|/** Truncate an extracted value at any trailing save/remember/request phrase.
    84| *  Also strips leading punctuation (period, comma) left behind when the phrase
    85| *  follows a sentence boundary — e.g. "Ivan. Please save and remember" → "Ivan". */
    86|function truncateAtSavePhrase(value: string): string {
    87|  const stopWords = [
    88|    'can you save', 'save this', 'remember this', 'store this',
    89|    'save it', 'remember it', 'store it', 'save now', 'remember now', 'store now',
    90|    'please save', 'please remember', 'please store',
    91|    'save and remember', 'remember and save', 'save and store',
    92|    'please save and remember', 'please remember and save',
    93|    'and remember this', 'and save this', 'and store this',
    94|    'and remember it', 'and save it', 'and store it',
    95|    'remember this', 'save this', 'store this',
    96|  ];
    97|  const lower = value.toLowerCase();
    98|  let cutAt = value.length;
    99|  for (const phrase of stopWords) {
   100|    const idx = lower.indexOf(phrase);
   101|    if (idx >= 0 && idx < cutAt) cutAt = idx;
   102|  }
   103|  let result = value.slice(0, cutAt).trim();
   104|  // Strip trailing punctuation left behind after truncation
   105|  result = result.replace(/[.,;:!?]+$/g, '').trim();
   106|  return result;
   107|}
   108|
   109|/** Extend the generic name extraction with a fallback for "save this now" + identity phrases.
   110| *  Handles compound identity like "my company is X and I prefer to be called Y, remember this". */
   111|function extractIdentityValue(text: string): string | null {
   112|  const lower = text.toLowerCase();
   113|  let raw: string | null = null;
   114|  // Compound: "my company is X and I prefer to be called Y" → extract Y (the name)
   115|  if (lower.includes('prefer to be called') || lower.includes('call me')) {
   116|    const match = text.match(/\b(?:prefer\s+to\s+be\s+called|call\s+me)\s+(.+?)(?:\s*,?\s*(?:please\s+)?(?:save|remember|store)\s+(?:this|it|that))?\.?$/i);
   117|    if (match && match[1]) raw = match[1];
   118|  }
   119|  if (!raw && lower.includes('my name is')) {
   120|    const match = text.match(/\bmy\s+name\s+is\s+(.+?)(?:\s+(?:and\s+)?(?:save|remember|store)\s+it)?$/i);
   121|    if (match && match[1]) raw = match[1];
   122|  }
   123|  if (!raw && (lower.includes('i am') || lower.includes('i\'m') || lower.includes('i’m'))) {
   124|    const match = text.match(/\bi\s*['’]?m\s+(.+?)(?:\s+(?:and\s+)?(?:save|remember|store)\s+it)?$/i);
   125|    if (match && match[1]) raw = match[1];
   126|  }
   127|  if (!raw && (lower.includes('work at') || /\b(?:owner|ceo|founder)\s+of\b/.test(lower))) {
   128|    const match = text.match(/\b(?:work\s+at|(?:owner|ceo|founder)\s+of)\s+(.+?)(?:\s+(?:and\s+)?(?:save|remember|store)\s+it)?$/i);
   129|    if (match && match[1]) raw = match[1];
   130|  }
   131|  if (!raw) return null;
   132|  return cleanName(truncateAtSavePhrase(raw));
   133|}
   134|
   135|function cleanName(raw: string): string {
   136|  return raw
   137|    .trim()
   138|    .replace(/^["“']+|["”'.!?]+$/g, '')
   139|    .replace(/\s+/g, ' ')
   140|    .trim()
   141|    .slice(0, 120);
   142|}
   143|
   144|/**
   145| * Detect a memory command in the user's prompt. Returns null when the prompt is
   146| * not a memory command (so the normal AI flow continues untouched).
   147| *
   148| * This runs BEFORE the generic execution/knowledge classifier so memory phrases
   149| * ("save my name", "what is my name") are never misrouted to clarification.
   150| */
   151|export function parseMemoryCommand(prompt: string): MemoryCommand | null {
   152|  const text = prompt.trim();
   153|  if (!text) return null;
   154|
   155|  for (const re of FORGET_NAME_PATTERNS) {
   156|    if (re.test(text)) return { kind: 'forget_name', value: '' };
   157|  }
   158|  for (const re of SHOW_MEMORY_PATTERNS) {
   159|    if (re.test(text)) return { kind: 'show_memory', value: '' };
   160|  }
   161|  for (const re of CHANGE_NAME_PATTERNS) {
   162|    const match = text.match(re);
   163|    if (match && match[1]) {
   164|      const value = cleanName(truncateAtSavePhrase(match[1]));
   165|      if (value) return { kind: 'change_name', value };
   166|    }
   167|  }
   168|  for (const re of REMEMBER_NAME_PATTERNS) {
   169|    const match = text.match(re);
   170|    if (match && match[1]) {
   171|      const value = cleanName(truncateAtSavePhrase(match[1]));
   172|      if (value) return { kind: 'remember_name', value };
   173|    }
   174|  }
   175|
   176|  // Fallback: broad "save/remember this now" + identity phrase detector.
   177|  // Catches phrasing like "I will tell you ... save this now" which is a clear
   178|  // memory write intent even when the exact regexes above miss it.
   179|  if (isMemorySaveRequest(text)) {
   180|    const value = extractIdentityValue(text);
   181|    if (value) return { kind: 'remember_name', value };
   182|  }
   183|
   184|  return null;
   185|}
   186|
   187|export type MemoryCommandResult = {
   188|  answer: string;
   189|  profile: UserProfile | null;
   190|  command: MemoryCommandKind;
   191|};
   192|
   193|/**
   194| * Execute a parsed memory command against the durable store and return a natural
   195| * confirmation the user sees in chat.
   196| */
   197|export async function executeMemoryCommand(
   198|  userId: string,
   199|  command: MemoryCommand,
   200|): Promise<MemoryCommandResult> {
   201|  switch (command.kind) {
   202|    case 'remember_name':
   203|    case 'change_name': {
   204|      if (isSensitiveValue(command.value)) {
   205|        return {
   206|          answer: `I won't store that — it looks sensitive. ${IVX_IA_NAME} only remembers your name, company, role, language and preferred greeting.`,
   207|          profile: await getProfile(userId),
   208|          command: command.kind,
   209|        };
   210|      }
   211|      const result = await upsertProfile(userId, { fullName: command.value });
   212|      if (!result.ok) {
   213|        return { answer: result.error, profile: await getProfile(userId), command: command.kind };
   214|      }
   215|      const verb = command.kind === 'change_name' ? 'updated your name to' : 'will remember that your name is';
   216|      return {
   217|        answer: `Done. ${IVX_IA_NAME} ${verb} ${result.profile.fullName}. I'll greet you by name in every new conversation.`,
   218|        profile: result.profile,
   219|        command: command.kind,
   220|      };
   221|    }
   222|    case 'forget_name': {
   223|      const profile = await forgetName(userId);
   224|      return {
   225|        answer: `Done. ${IVX_IA_NAME} has forgotten your name. Everything else in your profile is unchanged.`,
   226|        profile,
   227|        command: command.kind,
   228|      };
   229|    }
   230|    case 'show_memory': {
   231|      const profile = await getProfile(userId);
   232|      return { answer: describeProfile(profile), profile, command: command.kind };
   233|    }
   234|    default:
   235|      return { answer: '', profile: null, command: command.kind };
   236|  }
   237|}
   238|
   239|/** Human-readable recall of everything IVX IA remembers about a user. */
   240|export function describeProfile(profile: UserProfile): string {
   241|  const lines: string[] = [`Here's what ${IVX_IA_NAME} remembers about you:`];
   242|  lines.push(`• Name: ${profile.fullName || '(not set)'}`);
   243|  if (profile.preferredName && profile.preferredName !== profile.fullName) {
   244|    lines.push(`• Preferred name: ${profile.preferredName}`);
   245|  }
   246|  lines.push(`• Company: ${profile.company || '(not set)'}`);
   247|  lines.push(`• Role: ${profile.role || '(not set)'}`);
   248|  if (profile.email) lines.push(`• Email: ${profile.email}`);
   249|  lines.push(`• Language: ${profile.language}`);
   250|  lines.push(`• Greeting style: ${profile.greetingStyle}`);
   251|  if (profile.lastSeenAt) lines.push(`• Last seen: ${profile.lastSeenAt}`);
   252|  return lines.join('\n');
   253|}
   254|
   255|/** Time-of-day part for the greeting, in the user's local-ish window. */
   256|function timeOfDayGreeting(date: Date): string {
   257|  const hour = date.getHours();
   258|  if (hour < 12) return 'Good morning';
   259|  if (hour < 18) return 'Good afternoon';
   260|  return 'Good evening';
   261|}
   262|
   263|/**
   264| * Build the cross-conversation greeting using the stored profile, e.g.
   265| *   "Good morning Ivan Perez. IVX IA is ready."
   266| * Falls back to a name-less greeting when no name is remembered yet.
   267| */
   268|export function buildGreeting(profile: UserProfile, now: Date = new Date()): string {
   269|  const name = (profile.preferredName || profile.fullName).trim();
   270|  let lead: string;
   271|  switch (profile.greetingStyle) {
   272|    case 'formal':
   273|      lead = name ? `Hello ${name}` : 'Hello';
   274|      break;
   275|    case 'casual':
   276|      lead = name ? `Hey ${name}` : 'Hey there';
   277|      break;
   278|    case 'time_of_day':
